# Generated by qa-agent from cases/cancellation.yaml. Do not edit: change the cases, then run qa-agent generate.
"""Cancellation and refund: 3 cases, one test each."""

from pathlib import Path

import pytest

from api_test_framework import Expect, load_rows, unique_id

PROJECT = Path(__file__).resolve().parents[2]
TC002_ROWS = load_rows(PROJECT / "data/cancellation_boundaries.csv")


@pytest.mark.functional
@pytest.mark.boundary
@pytest.mark.sanity
@pytest.mark.writes
@pytest.mark.case("TC002")
@pytest.mark.priority("P0")
@pytest.mark.parametrize("row", TC002_ROWS, ids=lambda row: str(row["case"]) if "case" in row else None)
def test_tc002_the_refund_at_the_24_hour_boundary(api, context, row):
    """The refund at the 24-hour boundary. Criteria: AC-2, AC-3."""
    unique = unique_id()
    # 1. POST /bookings
    response = api.post("/bookings", json={
        "passenger_name": f"Asha Rao {unique}",
        "email": f"asha.{unique}@testdata.example",
        "amount": 250,
        "booked_at": row["booked_at"],
    })
    Expect(response).status_is(201)
    context.remember("pnr", response.value("pnr"))
    # 2. POST /bookings/{{pnr}}/cancel
    response = api.post(f"/bookings/{context.get('pnr')}/cancel", json={"cancelled_at": row["cancelled_at"]})
    (Expect(response).status_is(200)
        .field_equals("refund_allowed", row["refund_allowed"])
        .field_equals("refund_amount", row["refund_amount"]))


@pytest.mark.functional
@pytest.mark.negative
@pytest.mark.writes
@pytest.mark.case("TC003")
@pytest.mark.priority("P1")
def test_tc003_a_second_cancel_is_refused(api, context):
    """A second cancel is refused. Criteria: AC-4."""
    unique = unique_id()
    # 1. POST /bookings
    response = api.post("/bookings", json={
        "passenger_name": f"Asha Rao {unique}",
        "email": f"asha.{unique}@testdata.example",
        "amount": 250,
        "booked_at": "2026-01-15T10:00:00Z",
    })
    Expect(response).status_is(201)
    context.remember("pnr", response.value("pnr"))
    # 2. POST /bookings/{{pnr}}/cancel
    response = api.post(f"/bookings/{context.get('pnr')}/cancel", json={"cancelled_at": "2026-01-15T11:00:00Z"})
    Expect(response).status_is(200)
    # 3. POST /bookings/{{pnr}}/cancel
    response = api.post(f"/bookings/{context.get('pnr')}/cancel", json={"cancelled_at": "2026-01-20T11:00:00Z"})
    Expect(response).status_is(409).field_equals("error.code", "already_cancelled")


@pytest.mark.functional
@pytest.mark.negative
@pytest.mark.writes
@pytest.mark.case("TC004")
@pytest.mark.priority("P2")
def test_tc004_an_unknown_pnr_cant_be_cancelled(api, context):
    """An unknown PNR can't be cancelled. Criteria: AC-4."""
    # 1. POST /bookings/NOPE99/cancel
    response = api.post("/bookings/NOPE99/cancel")
    Expect(response).status_is(404).field_equals("error.code", "booking_not_found")
